<?php
declare(strict_types=1);
require_once __DIR__.'/includes/functions.php';
$lang=lang();
$upcomingStmt=db()->query('SELECT * FROM events WHERE is_published=1 AND event_date>=CURDATE() ORDER BY event_date ASC,event_time ASC');$upcoming=$upcomingStmt->fetchAll();
$pastStmt=db()->query('SELECT * FROM events WHERE is_published=1 AND event_date<CURDATE() ORDER BY event_date DESC,event_time DESC LIMIT 6');$past=$pastStmt->fetchAll();
$pageTitle='Events';require __DIR__.'/includes/header.php';
?>
<section class="section"><div class="container"><div class="public-page-heading"><p class="eyebrow"><?=e(setting('events_eyebrow',"MEET · LEARN · PARTICIPATE"))?></p><h1 class="section-title"><?=e(setting('events_title',"Events and activities."))?></h1><p class="copy"><?=e(setting('events_intro',"Find a workshop, gathering or community activity and discover how to take part."))?></p></div>
<?php if($upcoming):?><div class="section-head listing-section-head"><div><h2 class="subsection-title"><?=e(setting('events_upcoming_title','Coming up'))?></h2><p class="muted"><?=e(setting('events_upcoming_intro','Upcoming published activities'))?></p></div></div><div class="grid-3 event-list-grid"><?php foreach($upcoming as $ev):?><article class="card event-card"><div class="card-media"><?php if($ev['featured_image']):?><img loading="lazy" src="<?=e($ev['featured_image'])?>" alt="<?=e(localTitle($ev,$lang))?>"><?php else:?><div class="media-placeholder media-event" aria-hidden="true"><span>COMMUNITY EVENT</span></div><?php endif;?></div><div class="card-body"><div class="meta-row"><span class="tag"><?=e(date('D, M j, Y',strtotime($ev['event_date'])))?></span><?php if($ev['capacity']):?><span class="muted"><?=e(setting('events_capacity_label','Capacity'))?>: <?=e((string)$ev['capacity'])?></span><?php endif;?></div><h2 class="content-card-title"><?=e(localTitle($ev,$lang))?></h2><div class="event-facts"><span>⌖ <?=e($ev['location'])?></span><span>◷ <?=e(substr((string)$ev['event_time'],0,5))?></span></div><p><?=e(mb_strimwidth(strip_tags(localDescription($ev,$lang)),0,155,'…'))?></p><a class="btn primary" href="event-detail.php?id=<?=$ev['id']?>"><?=e(setting('events_details_link','Event details'))?> <span aria-hidden="true">→</span></a></div></article><?php endforeach;?></div><?php else:?><div class="empty-state"><span class="empty-icon">⌁</span><h2><?=e(setting('events_empty_title','No upcoming events'))?></h2><p><?=e(setting('events_empty_text','There are no published events scheduled right now. Check the past activities below and come back for upcoming announcements.'))?></p><a class="btn ghost" href="<?=APP_URL?>/contact.php"><?=e(setting('events_empty_link','Ask us about activities'))?></a></div><?php endif;?>
<?php if($past):?><section class="past-events-section"><div class="section-head listing-section-head"><div><p class="eyebrow"><?=e(setting('events_past_eyebrow','FROM THE ARCHIVE'))?></p><h2 class="subsection-title"><?=e(setting('events_past_title','Past activities'))?></h2><p class="muted"><?=e(setting('events_past_intro','A look back at published ATACJL events.'))?></p></div></div><div class="past-event-list"><?php foreach($past as $ev):?><a class="past-event-row" href="event-detail.php?id=<?=$ev['id']?>"><span class="past-date"><strong><?=e(date('d',strtotime($ev['event_date'])))?></strong><small><?=e(date('M Y',strtotime($ev['event_date'])))?></small></span><span class="past-event-copy"><strong><?=e(localTitle($ev,$lang))?></strong><small><?=e($ev['location'])?> · <?=e(substr((string)$ev['event_time'],0,5))?></small></span><span class="past-event-arrow" aria-hidden="true">→</span></a><?php endforeach;?></div></section><?php endif;?>
</div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
